  function icon(parent,name,x,y,size=24,color='ink'){const raw=name==='rank-down'||name==='rank-up'?DATA.icons.arrow.replace(/(<svg[^>]*>)/,'$1<g transform="rotate('+(name==='rank-down'?90:-90)+' 128 128)">').replace('</svg>','</g></svg>'):DATA.icons[name]||DATA.icons.book;const n=figma.createNodeFromSvg(raw.replace(/currentColor/g,C[color]||color));n.name='Biểu tượng / '+name;n.resize(size,size);parent.appendChild(n);n.x=x;n.y=y;n.setPluginData('iconSource',name.startsWith('admin-')?'Thu Thanh AdminIcon':'Phosphor');return n;}
