    function split(axis){const pos=axis==='HORIZONTAL'?'x':'y',size=axis==='HORIZONTAL'?'width':'height',sorted=[...content].sort((a,b)=>a[pos]-b[pos]);const groups=[];let edge=-Infinity;for(const c of sorted){if(c[pos]>=edge-.01){groups.push([c]);edge=c[pos]+c[size];}else{groups[groups.length-1].push(c);edge=Math.max(edge,c[pos]+c[size]);}}return groups;}
